import express, { Request, Response, NextFunction } from 'express';
import { MongoClient, Db, Collection } from 'mongodb';
import crypto from 'crypto';
import { z } from 'zod';

const app = express();
app.use(express.json());

let db: Db;
let usersCollection: Collection;

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';
const DB_NAME = process.env.DB_NAME || 'appdb';

// Fail closed: require a real secret instead of a predictable default.
const SECRET_KEY = process.env.SECRET_KEY;
if (!SECRET_KEY || SECRET_KEY.length < 16) {
  throw new Error('SECRET_KEY environment variable must be set to a strong value');
}

// Schema validation for search parameters
const SearchSchema = z.object({
  field: z.enum(['username', 'email', 'department']),
  value: z.string().min(1).max(100),
  options: z.object({
    caseSensitive: z.boolean().optional(),
    exactMatch: z.boolean().optional()
  }).optional()
});

// Middleware: authenticate requests via HMAC token
function authMiddleware(req: Request, res: Response, next: NextFunction) {
  const token = req.headers['x-auth-token'] as string;
  if (!token) return res.status(401).json({ error: 'Missing token' });
  const [payload, sig] = token.split('.');
  if (!payload || !sig) return res.status(401).json({ error: 'Malformed token' });

  const expected = crypto.createHmac('sha256', SECRET_KEY)
    .update(payload).digest('hex');

  let sigBuf: Buffer;
  let expectedBuf: Buffer;
  try {
    sigBuf = Buffer.from(sig, 'hex');
    expectedBuf = Buffer.from(expected, 'hex');
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }

  // timingSafeEqual throws if lengths differ; guard first to avoid crashing.
  if (sigBuf.length !== expectedBuf.length || !crypto.timingSafeEqual(sigBuf, expectedBuf)) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  let decoded: any;
  try {
    decoded = JSON.parse(Buffer.from(payload, 'base64').toString());
  } catch {
    return res.status(401).json({ error: 'Malformed token' });
  }
  (req as any).user = decoded;
  next();
}

// Build a safe query filter from validated input
function buildQueryFilter(field: string, value: string, options?: { caseSensitive?: boolean; exactMatch?: boolean }) {
  const filter: Record<string, any> = {};

  if (options?.exactMatch) {
    filter[field] = value;
  } else {
    // Use regex for partial matching
    const escapedValue = escapeRegex(value);
    const flags = options?.caseSensitive ? '' : 'i';
    filter[field] = { $regex: escapedValue, $options: flags };
  }

  return filter;
}

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Query projection builder - determines which fields to return
function buildProjection(requestedFields: unknown): Record<string, number> {
  const defaultProjection = { username: 1, email: 1, department: 1, _id: 0 };

  if (!requestedFields || typeof requestedFields !== 'object') {
    return defaultProjection;
  }

  // Only allow whitelisted field names in projection
  const allowedFields = ['username', 'email', 'department', 'createdAt', 'role'];
  const projection: Record<string, number> = { _id: 0 };

  for (const [key, val] of Object.entries(requestedFields as Record<string, unknown>)) {
    if (allowedFields.includes(key) && (val === 1 || val === 0)) {
      projection[key] = val as number;
    }
  }

  return Object.keys(projection).length > 1 ? projection : defaultProjection;
}

// Sort parameter sanitizer
function buildSortOptions(sortParam: unknown): Record<string, 1 | -1> {
  const defaultSort = { username: 1 as const };
  if (!sortParam || typeof sortParam !== 'object') return defaultSort;

  const allowedSortFields = ['username', 'email', 'department', 'createdAt'];
  const sort: Record<string, 1 | -1> = {};

  for (const [key, val] of Object.entries(sortParam as Record<string, unknown>)) {
    if (allowedSortFields.includes(key) && (val === 1 || val === -1)) {
      sort[key] = val as 1 | -1;
    }
  }

  return Object.keys(sort).length > 0 ? sort : defaultSort;
}

// Advanced search with aggregation pipeline
app.post('/api/users/search', authMiddleware, async (req: Request, res: Response) => {
  try {
    const parseResult = SearchSchema.safeParse(req.body.search);
    if (!parseResult.success) {
      return res.status(400).json({ error: 'Invalid search parameters', details: parseResult.error });
    }

    const { field, value, options } = parseResult.data;
    const filter = buildQueryFilter(field, value, options);
    const projection = buildProjection(req.body.projection);
    const sort = buildSortOptions(req.body.sort);
    const limit = Math.min(Math.max(parseInt(req.body.limit) || 20, 1), 100);

    // Build aggregation pipeline for complex queries
    const pipeline: any[] = [
      { $match: filter },
      { $project: projection },
      { $sort: sort },
      { $limit: limit }
    ];

    // Apply additional filters from user context
    const userContext = (req as any).user;
    if (userContext.scope && userContext.scope !== 'admin') {
      // Non-admin users can only see their own department
      pipeline.unshift({ $match: { department: userContext.department } });
    }

    const results = await usersCollection.aggregate(pipeline).toArray();
    res.json({ results, count: results.length });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Lookup endpoint - find user by computed identifier
app.get('/api/users/lookup', authMiddleware, async (req: Request, res: Response) => {
  try {
    const identifier = req.query.id as string;
    if (!identifier || typeof identifier !== 'string' || identifier.length > 64) {
      return res.status(400).json({ error: 'Invalid identifier' });
    }

    // Compute lookup key from identifier
    const lookupKey = computeLookupKey(identifier, (req as any).user);

    const user = await usersCollection.findOne(
      lookupKey,
      { projection: { password: 0, internalNotes: 0 } }
    );

    if (!user) return res.status(404).json({ error: 'User not found' });
    res.json({ user });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Compute the lookup key based on identifier format and user context
function computeLookupKey(identifier: string, userContext: any): Record<string, any> {
  // If identifier looks like an email, search by email
  if (identifier.includes('@')) {
    return { email: identifier };
  }

  // If identifier is a hex string of length 24, treat as ObjectId-like lookup
  if (/^[a-f0-9]{24}$/.test(identifier)) {
    return { internalId: identifier };
  }

  // Otherwise, build a compound lookup using the user's filter preferences
  // stored in their JWT context - only use safe string values
  const baseFilter: Record<string, any> = { username: identifier };

  if (userContext.lookupFilters && typeof userContext.lookupFilters === 'object') {
    // Only merge string-valued filters from allowed fields
    const allowedLookupFields = ['department', 'role'];
    for (const [key, val] of Object.entries(userContext.lookupFilters)) {
      if (allowedLookupFields.includes(key) && typeof val === 'string' && val.length <= 64) {
        baseFilter[key] = val;
      }
    }
  }

  return baseFilter;
}

async function main() {
  const client = await MongoClient.connect(MONGO_URI);
  db = client.db(DB_NAME);
  usersCollection = db.collection('users');

  await usersCollection.createIndex({ username: 1 });
  await usersCollection.createIndex({ email: 1 });
  await usersCollection.createIndex({ department: 1 });

  app.listen(3000, () => console.log('Server running on port 3000'));
}

main().catch(console.error);
